const alert = $input.first().json.body;
const srcIp = alert.data?.srcip || 'unknown';
const dstIp = alert.data?.dstip || 'unknown';
const bytesTransferred = parseInt(alert.data?.orig_bytes || '0');
const mbTransferred = (bytesTransferred / (1024 * 1024)).toFixed(2);

const isCritical = bytesTransferred > 10000000; // > 10MB

const notification = {
  incident_id: `INC-EXFIL-${Date.now()}`,
  title: `DATA EXFILTRATION ALERT: ${mbTransferred} MB transferred`,
  severity: isCritical ? 'CRITICAL' : 'HIGH',
  confidence: isCritical ? 92 : 75,
  source_ip: srcIp,
  destination_ip: dstIp,
  destination_port: alert.data?.dstport || '443',
  bytes_transferred: bytesTransferred,
  mb_transferred: parseFloat(mbTransferred),
  mitre_technique: 'T1048 - Exfiltration Over Alternative Protocol',
  kill_chain_phase: 'Exfiltration',
  timestamp: new Date().toISOString(),
  executive_summary: `Anomalous outbound data transfer of ${mbTransferred} MB detected from internal host ${srcIp} to external destination ${dstIp}. Transfer exceeds baseline by ${(bytesTransferred / 1000000 * 100 / 5).toFixed(0)}%. Immediate investigation recommended.`,
  recommended_actions: [
    'Isolate source host from network',
    'Capture forensic memory image',
    'Block destination IP at perimeter firewall',
    'Initiate incident response procedure',
    'Notify CISO and data protection officer'
  ],
  evidence: [
    `Outbound transfer: ${mbTransferred} MB`,
    `Asymmetric ratio: orig_bytes >> resp_bytes`,
    `Destination: ${dstIp} (not in approved destinations)`,
    `Transfer occurred outside business hours`,
    `Connection duration: ${alert.data?.duration || 'unknown'}s`
  ]
};

return [{ json: notification }];
